pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }

    receive() external payable {}

    function testFuzz_property(uint256 fundAmount, uint256 withdrawValue) public {
        fundAmount = bound(fundAmount, 1, 1 ether);
        withdrawValue = bound(withdrawValue, 1, 1 ether);

        address funder = address(0xF00D);
        vm.deal(funder, fundAmount);
        vm.prank(funder);
        address(c).call{value: fundAmount}("");

        vm.deal(address(this), withdrawValue);
        c.withdraw{value: withdrawValue}();

        assertTrue(address(c).balance == 0);
    }
}
